import ViewIcon from '@root/frontend/assets/icons/interface/View'
import ViewHiddenIcon from '@root/frontend/assets/icons/interface/ViewHidden'
import { cn } from '@root/frontend/utils/cn'
import type { OpcUaTrustedCertificate, OpcUaUser } from '@root/middleware/shared/ports/types'
import { useCallback, useEffect, useMemo, useState } from 'react'
import { v4 as uuidv4 } from 'uuid'

import { InputWithRef } from '../../../../../../_atoms/input'
import { Label } from '../../../../../../_atoms/label'
import { Select, SelectContent, SelectItem, SelectTrigger } from '../../../../../../_atoms/select'
import { Modal, ModalContent, ModalFooter, ModalHeader, ModalTitle } from '../../../../../../_molecules/modal'

type AuthType = 'password' | 'certificate'
type UserRole = 'viewer' | 'operator' | 'engineer'

interface UserModalProps {
  isOpen: boolean
  onClose: () => void
  onSave: (user: OpcUaUser) => void
  existingUser?: OpcUaUser
  existingUsernames: string[]
  trustedCertificates: OpcUaTrustedCertificate[]
  usedCertificateIds: string[]
}

const inputStyles =
  'h-[30px] w-full rounded-md border border-neutral-300 bg-white px-2 py-1 font-caption !text-xs font-medium text-neutral-850 outline-none focus:border-brand-medium-dark dark:border-neutral-850 dark:bg-neutral-950 dark:text-neutral-300'

const ROLE_OPTIONS: { value: UserRole; label: string; description: string }[] = [
  { value: 'viewer', label: 'Viewer', description: 'Read-only access to all variables' },
  { value: 'operator', label: 'Operator', description: 'Read/Write based on per-variable permission settings' },
  { value: 'engineer', label: 'Engineer', description: 'Full administrative access' },
]

// PBKDF2 configuration - matches OpenPLC Runtime's expected format
// Using PBKDF2 instead of bcrypt for cross-platform compatibility (MSYS2/Windows)
const PBKDF2_ITERATIONS = 600000 // OWASP recommendation for SHA-256
const PBKDF2_SALT_LENGTH = 16
const PBKDF2_HASH_LENGTH = 32 // SHA-256 output length

/**
 * Hash a password using PBKDF2-HMAC-SHA256.
 * Format: pbkdf2:sha256:iterations$base64_salt$base64_hash
 * This format is compatible with OpenPLC Runtime on all platforms.
 */
const hashPassword = async (password: string): Promise<string> => {
  // Generate random salt
  const salt = crypto.getRandomValues(new Uint8Array(PBKDF2_SALT_LENGTH))

  // Import password as key material
  const passwordKey = await crypto.subtle.importKey('raw', new TextEncoder().encode(password), 'PBKDF2', false, [
    'deriveBits',
  ])

  // Derive hash using PBKDF2
  const hashBuffer = await crypto.subtle.deriveBits(
    {
      name: 'PBKDF2',
      salt: salt,
      iterations: PBKDF2_ITERATIONS,
      hash: 'SHA-256',
    },
    passwordKey,
    PBKDF2_HASH_LENGTH * 8, // bits
  )

  // Convert to base64
  const saltB64 = btoa(String.fromCharCode(...salt))
  const hashB64 = btoa(String.fromCharCode(...new Uint8Array(hashBuffer)))

  // Return in format expected by OpenPLC Runtime
  return `pbkdf2:sha256:${PBKDF2_ITERATIONS}$${saltB64}$${hashB64}`
}

export const UserModal = ({
  isOpen,
  onClose,
  onSave,
  existingUser,
  existingUsernames,
  trustedCertificates,
  usedCertificateIds,
}: UserModalProps) => {
  const isEditing = !!existingUser

  // Form state
  const [authType, setAuthType] = useState<AuthType>('password')
  const [username, setUsername] = useState('')
  const [password, setPassword] = useState('')
  const [confirmPassword, setConfirmPassword] = useState('')
  const [showPassword, setShowPassword] = useState(false)
  const [certificateId, setCertificateId] = useState<string | null>(null)
  const [role, setRole] = useState<UserRole>('operator')

  // Reset form when modal opens/closes or user changes
  useEffect(() => {
    if (isOpen && existingUser) {
      setAuthType(existingUser.type)
      setUsername(existingUser.username ?? '')
      setPassword('')
      setConfirmPassword('')
      setShowPassword(false)
      setCertificateId(existingUser.certificateId)
      setRole(existingUser.role)
    } else if (isOpen && !existingUser) {
      // Reset to defaults for new user
      setAuthType('password')
      setUsername('')
      setPassword('')
      setConfirmPassword('')
      setShowPassword(false)
      setCertificateId(null)
      setRole('operator')
    }
  }, [isOpen, existingUser])

  // Available certificates (not bound to other users, or bound to current user when editing)
  const availableCertificates = useMemo(() => {
    return trustedCertificates.filter(
      (cert) => !usedCertificateIds.includes(cert.id) || existingUser?.certificateId === cert.id,
    )
  }, [trustedCertificates, usedCertificateIds, existingUser])

  // Per-field validation. Each error string surfaces inline under its
  // corresponding input rather than in a bottom validation card — same
  // pattern the password-mismatch label uses.
  //
  // The mismatch and "passwords-not-yet-confirmed" gates live in their
  // own flags below since they have different visibility rules from
  // the field-error pattern (mismatch is only shown once the user has
  // typed in confirmPassword; missing confirmPassword silently
  // disables Save without a label).

  const usernameError = useMemo<string | null>(() => {
    if (authType !== 'password') return null
    if (!username.trim()) return 'Username is required'
    if (username.length > 64) return 'Username must be 64 characters or less'
    const isDuplicate = existingUsernames.some(
      (existingName) =>
        existingName.toLowerCase() === username.trim().toLowerCase() &&
        (!existingUser || existingUser.username?.toLowerCase() !== existingName.toLowerCase()),
    )
    if (isDuplicate) return 'A user with this username already exists'
    return null
  }, [authType, username, existingUsernames, existingUser])

  const passwordError = useMemo<string | null>(() => {
    if (authType !== 'password') return null
    // Editing path: an empty password means "keep existing" — not an error.
    if (isEditing && !password) return null
    if (!password) return 'Password is required'
    if (password.length < 4) return 'Password must be at least 4 characters'
    return null
  }, [authType, password, isEditing])

  const certificateError = useMemo<string | null>(() => {
    if (authType !== 'certificate') return null
    if (availableCertificates.length === 0 && !existingUser?.certificateId) {
      // The certificate-auth section already renders this banner inline
      // when there are no trusted certs. Skip surfacing it as a duplicate
      // field error.
      return null
    }
    if (!certificateId) return 'Please select a certificate'
    return null
  }, [authType, certificateId, availableCertificates, existingUser])

  // Password mismatch handling has two flavours:
  //   - `passwordsMismatchVisible`: drives the inline red label under the
  //     Confirm Password input. Only true once the user has typed something
  //     in confirmPassword, so the error doesn't flicker while they're still
  //     filling out the form.
  //   - `passwordsOk`: gates the Save button. Requires both fields to be
  //     filled AND match when a password is being set (new user, or editing
  //     user with non-empty password). Empty confirmPassword keeps Save
  //     disabled silently — no error is shown until the user types into the
  //     confirm field.
  const isSettingPassword = authType === 'password' && (!isEditing || password.length > 0)
  const passwordsMismatchVisible = isSettingPassword && confirmPassword.length > 0 && password !== confirmPassword
  const passwordsOk = !isSettingPassword || (confirmPassword.length > 0 && password === confirmPassword)

  const isValid = !usernameError && !passwordError && !certificateError && passwordsOk

  // Handle save
  const handleSave = useCallback(async () => {
    if (!isValid) return

    let passwordHash: string | null = null

    if (authType === 'password' && password) {
      passwordHash = await hashPassword(password)
    } else if (authType === 'password' && isEditing && existingUser?.passwordHash) {
      // Keep existing password hash if not changing
      passwordHash = existingUser.passwordHash
    }

    const user: OpcUaUser = {
      id: existingUser?.id ?? uuidv4(),
      type: authType,
      username: authType === 'password' ? username.trim() : null,
      passwordHash: authType === 'password' ? passwordHash : null,
      certificateId: authType === 'certificate' ? certificateId : null,
      role,
    }

    onSave(user)
    onClose()
  }, [isValid, authType, username, password, certificateId, role, existingUser, isEditing, onSave, onClose])

  return (
    <Modal open={isOpen} onOpenChange={(open) => !open && onClose()}>
      <ModalContent className='h-auto max-h-[90vh] w-[500px]' onClose={onClose}>
        <ModalHeader>
          <ModalTitle>{isEditing ? 'Edit User' : 'Add User'}</ModalTitle>
        </ModalHeader>

        <div className='flex flex-1 flex-col gap-4 overflow-y-auto'>
          {/* Authentication Type */}
          <div className='flex flex-col gap-2'>
            <Label className='text-xs font-semibold text-neutral-950 dark:text-white'>Authentication Type</Label>
            <Select value={authType} onValueChange={(v) => setAuthType(v as AuthType)}>
              <SelectTrigger
                withIndicator
                placeholder='Select type'
                className='flex h-[30px] w-full items-center justify-between gap-1 rounded-md border border-neutral-300 bg-white px-2 py-1 font-caption !text-xs font-medium text-neutral-850 outline-none data-[state=open]:border-brand-medium-dark dark:border-neutral-850 dark:bg-neutral-950 dark:text-neutral-300'
              />
              <SelectContent className='h-fit max-h-[200px] w-[--radix-select-trigger-width] overflow-y-auto rounded-lg border border-neutral-300 bg-white outline-none drop-shadow-lg dark:border-brand-medium-dark dark:bg-neutral-950'>
                <SelectItem
                  value='password'
                  className={cn(
                    'data-[state=checked]:[&:not(:hover)]:bg-neutral-100 data-[state=checked]:dark:[&:not(:hover)]:bg-neutral-900',
                    'flex w-full cursor-pointer items-center justify-start px-2 py-1 outline-none hover:bg-neutral-100 dark:hover:bg-neutral-800',
                  )}
                >
                  <span className='text-start font-caption text-xs font-normal text-neutral-700 dark:text-neutral-100'>
                    Password
                  </span>
                </SelectItem>
                <SelectItem
                  value='certificate'
                  className={cn(
                    'data-[state=checked]:[&:not(:hover)]:bg-neutral-100 data-[state=checked]:dark:[&:not(:hover)]:bg-neutral-900',
                    'flex w-full cursor-pointer items-center justify-start px-2 py-1 outline-none hover:bg-neutral-100 dark:hover:bg-neutral-800',
                  )}
                >
                  <span className='text-start font-caption text-xs font-normal text-neutral-700 dark:text-neutral-100'>
                    Certificate
                  </span>
                </SelectItem>
              </SelectContent>
            </Select>
          </div>

          {/* Password Authentication Section */}
          {authType === 'password' && (
            <div className='flex flex-col gap-4 rounded-lg border border-neutral-200 bg-neutral-50 p-4 dark:border-neutral-800 dark:bg-neutral-900'>
              <h4 className='font-caption text-xs font-semibold text-neutral-950 dark:text-white'>
                Password Authentication
              </h4>

              {/* Username */}
              <div className='flex flex-col gap-2'>
                <Label className='text-xs text-neutral-950 dark:text-white'>Username</Label>
                <InputWithRef
                  type='text'
                  value={username}
                  onChange={(e) => setUsername(e.target.value)}
                  placeholder='e.g., operator1'
                  maxLength={64}
                  className={inputStyles}
                />
                {usernameError && (
                  <span className='font-caption text-cp-xs font-normal text-red-500'>{usernameError}</span>
                )}
              </div>

              {/* Password */}
              <div className='flex flex-col gap-2'>
                <Label className='text-xs text-neutral-950 dark:text-white'>
                  {isEditing ? 'New Password (leave blank to keep current)' : 'Password'}
                </Label>
                <div className='relative'>
                  <InputWithRef
                    type={showPassword ? 'text' : 'password'}
                    value={password}
                    onChange={(e) => setPassword(e.target.value)}
                    placeholder='••••••••'
                    className={cn(inputStyles, 'pr-10')}
                  />
                  <button
                    type='button'
                    onClick={() => setShowPassword(!showPassword)}
                    disabled={!password}
                    className={cn(
                      'absolute right-2 top-1/2 -translate-y-1/2',
                      password
                        ? 'text-neutral-500 hover:text-neutral-700 dark:hover:text-neutral-300'
                        : 'cursor-not-allowed text-neutral-300 dark:text-neutral-600',
                    )}
                    title={
                      !password
                        ? 'Enter a password to toggle visibility'
                        : showPassword
                          ? 'Hide password'
                          : 'Show password'
                    }
                  >
                    {showPassword ? (
                      <ViewHiddenIcon size='sm' className='h-4 w-4 fill-current' />
                    ) : (
                      <ViewIcon size='sm' className='h-4 w-4 fill-current' />
                    )}
                  </button>
                </div>
                {passwordError && (
                  <span className='font-caption text-cp-xs font-normal text-red-500'>{passwordError}</span>
                )}
              </div>

              {/* Confirm Password */}
              <div className='flex flex-col gap-2'>
                <Label className='text-xs text-neutral-950 dark:text-white'>Confirm Password</Label>
                <InputWithRef
                  type={showPassword ? 'text' : 'password'}
                  value={confirmPassword}
                  onChange={(e) => setConfirmPassword(e.target.value)}
                  placeholder='••••••••'
                  className={inputStyles}
                />
                {passwordsMismatchVisible && (
                  <span className='font-caption text-cp-xs font-normal text-red-500'>Passwords do not match</span>
                )}
              </div>
            </div>
          )}

          {/* Certificate Authentication Section */}
          {authType === 'certificate' && (
            <div className='flex flex-col gap-4 rounded-lg border border-neutral-200 bg-neutral-50 p-4 dark:border-neutral-800 dark:bg-neutral-900'>
              <h4 className='font-caption text-xs font-semibold text-neutral-950 dark:text-white'>
                Certificate Authentication
              </h4>

              {availableCertificates.length === 0 ? (
                <p className='text-xs text-neutral-700 dark:text-neutral-300'>
                  No trusted certificates available. Add certificates in the Certificates tab first.
                </p>
              ) : (
                <div className='flex flex-col gap-2'>
                  <Label className='text-xs text-neutral-950 dark:text-white'>Client Certificate</Label>
                  <Select value={certificateId ?? ''} onValueChange={(v) => setCertificateId(v || null)}>
                    <SelectTrigger
                      withIndicator
                      placeholder='Select certificate'
                      className='flex h-[30px] w-full items-center justify-between gap-1 rounded-md border border-neutral-300 bg-white px-2 py-1 font-caption !text-xs font-medium text-neutral-850 outline-none data-[state=open]:border-brand-medium-dark dark:border-neutral-850 dark:bg-neutral-950 dark:text-neutral-300'
                    />
                    <SelectContent className='h-fit max-h-[200px] w-[--radix-select-trigger-width] overflow-y-auto rounded-lg border border-neutral-300 bg-white outline-none drop-shadow-lg dark:border-brand-medium-dark dark:bg-neutral-950'>
                      {availableCertificates.map((cert) => (
                        <SelectItem
                          key={cert.id}
                          value={cert.id}
                          className={cn(
                            'data-[state=checked]:[&:not(:hover)]:bg-neutral-100 data-[state=checked]:dark:[&:not(:hover)]:bg-neutral-900',
                            'flex w-full cursor-pointer items-center justify-start px-2 py-1 outline-none hover:bg-neutral-100 dark:hover:bg-neutral-800',
                          )}
                        >
                          <span className='text-start font-caption text-xs font-normal text-neutral-700 dark:text-neutral-100'>
                            {cert.id} {cert.subject && `(${cert.subject})`}
                          </span>
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                  <span className='text-xs text-neutral-500 dark:text-neutral-400'>
                    Select from trusted certificates configured in the Certificates tab
                  </span>
                  {certificateError && (
                    <span className='font-caption text-cp-xs font-normal text-red-500'>{certificateError}</span>
                  )}
                </div>
              )}
            </div>
          )}

          {/* User Role Section */}
          <div className='flex flex-col gap-4 rounded-lg border border-neutral-200 bg-neutral-50 p-4 dark:border-neutral-800 dark:bg-neutral-900'>
            <h4 className='font-caption text-xs font-semibold text-neutral-950 dark:text-white'>User Role</h4>

            <div className='flex flex-col gap-2'>
              <Label className='text-xs text-neutral-950 dark:text-white'>Role</Label>
              <Select value={role} onValueChange={(v) => setRole(v as UserRole)}>
                <SelectTrigger
                  withIndicator
                  placeholder='Select role'
                  className='flex h-[30px] w-full items-center justify-between gap-1 rounded-md border border-neutral-300 bg-white px-2 py-1 font-caption !text-xs font-medium text-neutral-850 outline-none data-[state=open]:border-brand-medium-dark dark:border-neutral-850 dark:bg-neutral-950 dark:text-neutral-300'
                />
                <SelectContent className='h-fit max-h-[200px] w-[--radix-select-trigger-width] overflow-y-auto rounded-lg border border-neutral-300 bg-white outline-none drop-shadow-lg dark:border-brand-medium-dark dark:bg-neutral-950'>
                  {ROLE_OPTIONS.map((option) => (
                    <SelectItem
                      key={option.value}
                      value={option.value}
                      className={cn(
                        'data-[state=checked]:[&:not(:hover)]:bg-neutral-100 data-[state=checked]:dark:[&:not(:hover)]:bg-neutral-900',
                        'flex w-full cursor-pointer items-center justify-start px-2 py-1 outline-none hover:bg-neutral-100 dark:hover:bg-neutral-800',
                      )}
                    >
                      <span className='text-start font-caption text-xs font-normal text-neutral-700 dark:text-neutral-100'>
                        {option.label}
                      </span>
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            {/* Role Descriptions */}
            <div className='mt-2 space-y-1'>
              {ROLE_OPTIONS.map((option) => (
                <p
                  key={option.value}
                  className={cn(
                    'text-xs',
                    role === option.value
                      ? 'font-medium text-neutral-950 dark:text-white'
                      : 'text-neutral-500 dark:text-neutral-400',
                  )}
                >
                  • {option.label}: {option.description}
                </p>
              ))}
            </div>
          </div>
        </div>

        <ModalFooter className='mt-4 flex justify-end gap-2'>
          <button
            type='button'
            onClick={onClose}
            className='h-[32px] rounded-md border border-neutral-300 bg-white px-4 font-caption !text-xs font-medium text-neutral-700 hover:bg-neutral-50 dark:border-neutral-700 dark:bg-neutral-800 dark:text-neutral-200 dark:hover:bg-neutral-700'
          >
            Cancel
          </button>
          <button
            type='button'
            onClick={() => void handleSave()}
            disabled={!isValid}
            className={cn(
              'h-[32px] rounded-md bg-brand px-4 font-caption !text-xs font-medium text-white hover:bg-brand-medium-dark',
              !isValid && 'cursor-not-allowed opacity-50',
            )}
          >
            {isEditing ? 'Save Changes' : 'Add User'}
          </button>
        </ModalFooter>
      </ModalContent>
    </Modal>
  )
}
