import { useCallback, useEffect, useRef, useState } from 'react'

import { useOpenPLCStore } from '../../../store'
import { extractSearchQuery } from '../../../store/slices/search/utils'
import { cn } from '../../../utils/cn'
import { InputWithRef } from '../input'

export const GenericTextCell = ({
  value,
  onChange,
  onBlur,
  editable = false,
  selected = false,
}: {
  value: string
  onChange: (value: string) => void
  onBlur: () => void
  editable?: boolean
  selected?: boolean
}) => {
  const inputRef = useRef<HTMLInputElement>(null)

  const { searchQuery } = useOpenPLCStore()
  const formattedCellValue = searchQuery ? extractSearchQuery(value, searchQuery) : value

  const [isEditing, setIsEditing] = useState(false)
  const handleStartEditing = useCallback(() => {
    if (editable && selected) {
      setIsEditing(true)
    }
  }, [editable, selected])
  const handleStopEditing = useCallback(() => {
    setIsEditing(false)
  }, [])

  useEffect(() => {
    if (isEditing && inputRef.current) {
      inputRef.current.focus()
      inputRef.current.select()
    }
  }, [isEditing])

  return isEditing ? (
    <InputWithRef
      ref={inputRef}
      value={value}
      onChange={(e) => {
        onChange(e.target.value)
      }}
      onBlur={() => {
        handleStopEditing()
        onBlur()
      }}
      className={cn('flex w-full flex-1 bg-transparent p-2 text-center outline-none')}
    />
  ) : (
    <div
      onClick={handleStartEditing}
      className={cn('flex w-full flex-1 cursor-text bg-transparent p-2 text-center outline-none', {
        'pointer-events-none': !selected,
        'cursor-not-allowed': !editable,
      })}
    >
      <p
        className={cn('h-4 w-full max-w-[400px] overflow-hidden text-ellipsis break-all')}
        dangerouslySetInnerHTML={{ __html: formattedCellValue }}
      />
    </div>
  )
}
